-- ============================================================================
-- V2: date-indexed historical FX rate store (PostgreSQL).
-- Period-correct currency conversion for portfolio analytics. Forward-only;
-- do not edit V1 (already applied) - schema changes go in new migrations.
-- ============================================================================

create table exchange_rates (
    id            bigint generated by default as identity primary key,
    version       bigint          not null,
    created_at    timestamp(6)    not null,
    updated_at    timestamp(6)    not null,
    created_by    varchar(100),
    updated_by    varchar(100),
    from_currency varchar(3)      not null,
    to_currency   varchar(3)      not null,
    as_of         date            not null,
    rate          numeric(19, 10) not null,
    constraint uq_fx_pair_asof unique (from_currency, to_currency, as_of)
);
create index idx_fx_pair_asof on exchange_rates (from_currency, to_currency, as_of);
